mapper.sql:
WHERE (#{role}='HQ_ADMIN' OR (#{role}='ENGINEER' AND t.assignee_id=#{actor}) OR (#{role}='STORE_MANAGER' AND EXISTS(SELECT 1 FROM repair_member_stores ms WHERE ms.user_id=#{actor} AND ms.store_id=t.store_id)))
AND t.store_id=#{storeId}AND t.status=#{status}AND t.priority=#{priority}AND t.assignee_id=#{assignee}
AND t.submitted_at>=#{from}AND t.submitted_at<#{to}
AND (t.ticket_no LIKE #{keyword} ESCAPE '!' OR t.title LIKE #{keyword} ESCAPE '!' OR JSON_UNQUOTE(JSON_EXTRACT(t.facility_snapshot,'$.facilityName')) LIKE #{keyword} ESCAPE '!')
